import Ajv from 'ajv';
import type {ValidateFunction} from 'ajv';
import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';

export interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}

export interface ToolContext {
  userId: string | number;
  sessionId?: string;
  workspaceId?: string | number;
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
  return typeof response === 'string' ? {result: response} : response;
}

export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);

export interface RegisteredTool {
  definition: ToolDefinition;
  execute: ToolExecutor;
}

interface StoredTool {
  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
  validate?: InputValidator;
}

type InputValidator = ValidateFunction;

function validationPath(error: NonNullable<ValidateFunction['errors']>[number] | undefined): string {
  const params = error?.params as {missingProperty?: string} | undefined;
  const paths = error as {instancePath?: string; dataPath?: string} | undefined;
  if (error?.keyword === 'required') {
    const property = params?.missingProperty?.replaceAll('~', '~0').replaceAll('/', '~1');
    return property ? `${paths?.instancePath ?? ''}/${property}` : '';
  }
  if (paths?.instancePath) return paths.instancePath;
  if (paths?.dataPath) return paths.dataPath.replace(/^\./, '/');
  const schemaPath = error?.schemaPath;
  const propertyMatch = schemaPath?.match(/\/properties\/([^/]+)(?:\/|$)/);
  const property = propertyMatch?.[1];
  return property ? `/${property.replaceAll('~1', '/').replaceAll('~0', '~')}` : '';
}

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();
  private readonly ajv = new Ajv({strict: false, validateFormats: false} as never);
  private readonly dynamicValidators = new WeakMap<object, InputValidator>();

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  private validatorFor(tool: StoredTool, definition: ToolDefinition): InputValidator {
    if (tool.validate) return tool.validate;
    const schema = definition.inputSchema;
    const cached = this.dynamicValidators.get(schema);
    if (cached) return cached;
    const validate = this.ajv.compile(schema);
    this.dynamicValidators.set(schema, validate);
    return validate;
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    let validate: InputValidator | undefined;
    if (typeof definition !== 'function') {
      try {
        validate = this.ajv.compile(resolved.inputSchema);
      } catch (error) {
        throw new Error(`Invalid inputSchema for tool ${resolved.name}`, {cause: error});
      }
    }
    this.tools.set(resolved.name, {definitionSource: definition, execute, validate});
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  /** Executes a tool under the input-validation contract in specs/hal-engine-tool-input-validation/spec.md. */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    const definition = this.resolveDefinition(tool.definitionSource);
    const validate = this.validatorFor(tool, definition);
    if (validate(input) !== true) {
      const error = validate.errors?.[0];
      const path = validationPath(error);
      log.warn('tool', 'input validation rejected', {name, path: path || '/', constraint: error?.keyword ?? 'unknown'});
      return {result: `Tool input ${path || '/'} is ${error?.message ?? 'invalid'}`};
    }
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }
}
import {jest} from '@jest/globals';
import Ajv from 'ajv';
import {ToolRegistry} from './registry.js';
import {setLogger} from '../../shared/logger.js';
import type {Logger} from '../../shared/logger.js';

describe('ToolRegistry input validation', () => {
  afterEach(() => {
    jest.restoreAllMocks();
    setLogger(undefined);
  });

  it('returns a rejection for a missing required property without invoking the executor', async () => {
    const registry = new ToolRegistry();
    const execute = jest.fn(async () => 'sunny');
    registry.register(
      {
        name: 'get_weather',
        description: 'Get weather for a location',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      },
      execute
    );

    const response = await registry.execute('get_weather', {});
    const executorCalls = execute.mock.calls.length;

    expect({result: response.result, executorCalls}).toEqual({
      result: expect.stringMatching(/location.*required|required.*location/i),
      executorCalls: 0,
    });
  });

  it('names a wrong-typed property and its expected type without revealing its value', async () => {
    const logLines: string[] = [];
    const record = (category: string, message: string, fields?: Record<string, unknown>) => {
      logLines.push(JSON.stringify({category, message, fields}));
    };
    const logger: Logger = {debug: record, info: record, warn: record, error: record};
    setLogger(logger);
    const registry = new ToolRegistry();
    const execute = jest.fn(async () => 'found');
    registry.register(
      {
        name: 'find_customer',
        description: 'Find a customer by account identifier',
        inputSchema: {
          type: 'object',
          properties: {accountId: {type: 'string'}},
          required: ['accountId'],
        },
      },
      execute
    );

    const response = await registry.execute('find_customer', {accountId: 8675309});
    const executorCalls = execute.mock.calls.length;

    expect({
      result: response.result,
      resultLeaksValue: response.result.includes('8675309'),
      logs: logLines.join('\n'),
      logsLeakValue: logLines.join('\n').includes('8675309'),
      executorCalls,
    }).toEqual({
      result: expect.stringMatching(/accountId.*string|string.*accountId/),
      resultLeaksValue: false,
      logs: expect.stringMatching(/accountId.*type|type.*accountId/),
      logsLeakValue: false,
      executorCalls: 0,
    });
  });

  it('names the full path of a nested missing required property', async () => {
    const registry = new ToolRegistry();
    const execute = jest.fn(async () => 'sunny');
    registry.register(
      {
        name: 'get_weather',
        description: 'Get weather for an address',
        inputSchema: {
          type: 'object',
          properties: {
            address: {
              type: 'object',
              properties: {location: {type: 'string'}},
              required: ['location'],
            },
          },
          required: ['address'],
        },
      },
      execute
    );

    const response = await registry.execute('get_weather', {address: {}});

    expect(response.result).toMatch(/\/address\/location.*required|required.*\/address\/location/i);
  });

  it('throws at register time naming the tool when a static inputSchema cannot be compiled', () => {
    const registry = new ToolRegistry();
    const brokenTool = {
      name: 'broken_weather',
      description: 'Has an invalid JSON Schema type',
      inputSchema: {type: 'object', properties: {location: {type: 'not-a-json-schema-type'}}},
    };

    expect(() => registry.register(brokenTool, async () => 'unreachable')).toThrow(/broken_weather/);
  });

  it('reuses a compiled validator when a dynamic definition returns the same schema object', async () => {
    const compile = jest.spyOn(Ajv.prototype, 'compile');
    const registry = new ToolRegistry();
    const schema: Record<string, unknown> = {
      type: 'object',
      properties: {location: {type: 'string'}},
      required: ['location'],
    };
    registry.register(
      () => ({
        name: 'get_weather',
        description: 'Get weather for a location',
        inputSchema: schema,
      }),
      async () => 'sunny'
    );

    const responses = await Promise.all([
      registry.execute('get_weather', {location: 'Berlin'}),
      registry.execute('get_weather', {location: 'Paris'}),
    ]);
    const compileCalls = compile.mock.calls.length;

    expect({responses, compileCalls}).toEqual({
      responses: [{result: 'sunny'}, {result: 'sunny'}],
      compileCalls: 1,
    });
  });
});
# Tool Input Validation

| Field  | Value                |
| ------ | -------------------- |
| Issue  | re-cinq/HALEngine#37 |
| Status | In Progress          |

Every tool registered in `src/orchestration/tools/registry.ts` declares a JSON Schema `inputSchema` that is forwarded to the configured AI provider, and `ToolRegistry.execute` validates the model-supplied `input` against that schema before calling the tool's executor. When validation fails, `execute` returns a rejection `ToolResponse` describing what was wrong rather than throwing, so the orchestrator feeds the failure back to the model as a `tool_result` within the existing tool-round budget.

## Validation at execute time

- When `input` omits a property listed in `required`, `ToolRegistry.execute` returns a `ToolResponse` whose `result` names the missing property as required and never invokes the executor ([validated by: rejects input missing a required property with a ToolResponse and never calls the executor](../../src/orchestration/tools/registry.acceptance.test.ts#L22), [validated by: returns a rejection for a missing required property without invoking the executor](../../src/orchestration/tools/registry.test.ts#L13)).
- When `input` supplies a property whose value does not match its declared JSON Schema type, `ToolRegistry.execute` returns a `ToolResponse` naming the failing field path and expected type without invoking the executor; its rejection log names the field path and failed constraint, and neither `result` nor the log contains the offending property value ([validated by: rejects a wrong-typed property naming the field and expected type without leaking the offending value to the result or logs](../../src/orchestration/tools/registry.acceptance.test.ts#L52), [validated by: names a wrong-typed property and its expected type without revealing its value](../../src/orchestration/tools/registry.test.ts#L38)).
- A rejection for a missing nested required property names the property's full path, including its parent objects ([validated by: names the full path of a nested missing required property](../../src/orchestration/tools/registry.test.ts#L78)).
- When `input` satisfies `required`, declared property types and `enum`, `ToolRegistry.execute` invokes the executor once and passes the input object through unchanged — including undeclared extra properties — without injecting `additionalProperties: false`, coercing types or applying defaults.
- When `ToolRegistry.execute` is called with a tool name that has not been registered, it throws `Unknown tool: <name>` because an unregistered tool is a programming or configuration error rather than a recoverable input mistake.

## Schema compilation and caching

- A static `ToolDefinition` has its `inputSchema` compiled once at `register` time, so a schema that is not valid JSON Schema throws synchronously from `register` with an error message naming the offending tool ([validated by: throws at register time naming the tool when a static inputSchema cannot be compiled](../../src/orchestration/tools/registry.acceptance.test.ts#L100), [validated by: throws at register time naming the tool when a static inputSchema cannot be compiled](../../src/orchestration/tools/registry.test.ts#L105)).
- A static tool's `inputSchema` is compiled at `register` time and reused on every `execute` call without re-reading or re-compiling `definition.inputSchema`.
- A function-valued `ToolDefinitionSource` resolves its definition on each `execute` call and validates against the `inputSchema` returned for that call, caching compiled validators by schema object reference (`WeakMap`) so distinct returned schemas each enforce their own rules ([validated by: reuses a compiled validator when a dynamic definition returns the same schema object](../../src/orchestration/tools/registry.test.ts#L116)).

## Orchestrator tool-loop recovery

- Because a schema rejection returns a `ToolResponse` instead of throwing, `src/orchestration/chatOrchestrator.ts` sends the rejection `result` back to the provider as a `tool_result` message, allowing the model to issue a corrected tool call on the next round and complete the turn within `maxToolRounds` ([validated by: returns a schema rejection as a tool_result in the orchestrator loop so the model can correct the call on the next round](../../src/orchestration/tools/registry.acceptance.test.ts#L118)).
